from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer which diagonal family carries the stripe colors.
    candidates = []
    for kind in ('sum', 'diff'):
        lines = defaultdict(list)
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = r + c if kind == 'sum' else c - r
                    lines[k].append(color)
        clues = {k: values[0] for k, values in lines.items()
                 if len(set(values)) == 1}
        score = sum(len(lines[k]) ** 2 for k in clues)
        candidates.append((score, kind, clues))

    _, kind, clues = max(candidates, key=lambda item: item[0])
    if not clues:
        return [row[:] for row in grid]

    # The diagonal colors repeat; use the shortest cycle consistent with clues.
    period = None
    phases = None
    for p in range(1, 2 * max(h, w) + 1):
        trial = {}
        for k, color in clues.items():
            phase = k % p
            if phase in trial and trial[phase] != color:
                break
            trial[phase] = color
        else:
            period, phases = p, trial
            break
    if period is None:
        raise ValueError('inconsistent diagonal clues')

    # Extend missing phases by the nearest observed phase, preferring forward
    # along the selected diagonal direction in a tie.
    known = dict(phases)
    for phase in range(period):
        if phase in phases:
            continue
        for distance in range(1, period + 1):
            following = (phase + distance) % period
            preceding = (phase - distance) % period
            if preceding in known:
                phases[phase] = known[preceding]
                break
            if following in known:
                phases[phase] = known[following]
                break

    def diagonal(r, c):
        return r + c if kind == 'sum' else c - r

    return [[phases[diagonal(r, c) % period] for c in range(w)]
            for r in range(h)]

